    "root": {
      "id": "root-html-forms",
      "label": "HTML Forms",
      "icon": "📝",
      "type": "root",
      "summary": "Create interactive forms for collecting user input",
      "children": [
        {
          "id": "node-3801",
          "label": "How HTML Forms Work",
          "icon": "🔘",
          "color": "#ef4444",
          "summary": "When a form is submitted, the browser packages the named form controls and sends their values to the destination specified by the form's action…",
          "children": [
            {
              "id": "node-38011",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "When a form is submitted, the browser packages the named form controls and sends their values to the destination specified by the form's action…"
            },
            {
              "id": "node-38012",
              "label": "Key Detail",
              "icon": "💡",
              "badge": "Standard",
              "summary": "HTML creates the form interface, but a server-side application usually validates and processes the submitted data."
            }
          ]
        },
        {
          "id": "node-3802",
          "label": "The Form Element",
          "icon": "🔘",
          "color": "#84cc16",
          "summary": "The <form> element groups controls that belong together and defines where submitted data is sent.",
          "children": [
            {
              "id": "node-38021",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "The <form> element groups controls that belong together and defines where submitted data is sent."
            },
            {
              "id": "node-38022",
              "label": "Try It",
              "icon": "💡",
              "badge": "Example",
              "summary": "See the live, editable example for this topic in the lesson."
            },
            {
              "id": "node-38023",
              "label": "Code Snippet",
              "icon": "💻",
              "badge": "Code",
              "summary": "<form action=\"/submit\" method=\"post\">",
              "isCode": true
            }
          ]
        },
        {
          "id": "node-3803",
          "label": "Text Input and Label",
          "icon": "🔘",
          "color": "#3b82f6",
          "summary": "Use <input type=\"text\"> for a single-line text value. A <label> describes a control, and its for attribute should match the control's id.",
          "children": [
            {
              "id": "node-38031",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "Use <input type=\"text\"> for a single-line text value. A <label> describes a control, and its for attribute should match the control's id."
            },
            {
              "id": "node-38032",
              "label": "Key Detail",
              "icon": "💡",
              "badge": "Standard",
              "summary": "Clicking a label focuses or activates its associated control, and screen readers announce the label with the field."
            },
            {
              "id": "node-38033",
              "label": "Code Snippet",
              "icon": "💻",
              "badge": "Code",
              "summary": "<label for=\"first-name\">First name:</label>",
              "isCode": true
            }
          ]
        },
        {
          "id": "node-3804",
          "label": "Radio Buttons",
          "icon": "🔘",
          "color": "#a855f7",
          "summary": "Radio buttons let a user select one option from a group. Controls in the same group use the same name value, while each id is unique.",
          "children": [
            {
              "id": "node-38041",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "Radio buttons let a user select one option from a group. Controls in the same group use the same name value, while each id is unique."
            },
            {
              "id": "node-38042",
              "label": "Try It",
              "icon": "💡",
              "badge": "Example",
              "summary": "See the live, editable example for this topic in the lesson."
            },
            {
              "id": "node-38043",
              "label": "Code Snippet",
              "icon": "💻",
              "badge": "Code",
              "summary": "<label><input type=\"radio\" name=\"plan\" value=\"basic\"> Basic</label>",
              "isCode": true
            }
          ]
        },
        {
          "id": "node-3805",
          "label": "Checkboxes",
          "icon": "📌",
          "color": "#f97316",
          "summary": "Checkboxes let a user select one or more independent options. Related checkboxes can share a name, but each checkbox needs its own value.",
          "children": [
            {
              "id": "node-38051",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "Checkboxes let a user select one or more independent options. Related checkboxes can share a name, but each checkbox needs its own value."
            },
            {
              "id": "node-38052",
              "label": "Try It",
              "icon": "💡",
              "badge": "Example",
              "summary": "See the live, editable example for this topic in the lesson."
            },
            {
              "id": "node-38053",
              "label": "Code Snippet",
              "icon": "💻",
              "badge": "Code",
              "summary": "<label><input type=\"checkbox\" name=\"hobby\" value=\"coding\"> Coding</label>",
              "isCode": true
            }
          ]
        },
        {
          "id": "node-3806",
          "label": "Submit Buttons",
          "icon": "🔘",
          "color": "#14b8a6",
          "summary": "An <input type=\"submit\"> creates a submit button. The <button> element is also commonly used and receives its button text directly between its tags.",
          "children": [
            {
              "id": "node-38061",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "An <input type=\"submit\"> creates a submit button. The <button> element is also commonly used and receives its button text directly between its tags."
            },
            {
              "id": "node-38062",
              "label": "Key Detail",
              "icon": "💡",
              "badge": "Standard",
              "summary": "Follow modern HTML5 and WCAG 2.2 best practice for Submit Buttons."
            }
          ]
        },
        {
          "id": "node-3807",
          "label": "The Name Attribute for Inputs",
          "icon": "🔘",
          "color": "#ef4444",
          "summary": "Every input that should be submitted needs a name attribute. The submitted field is identified by that name, and the control's current value is…",
          "children": [
            {
              "id": "node-38071",
              "label": "Definition & Concept",
              "icon": "⚡",
              "badge": "Concept",
              "summary": "Every input that should be submitted needs a name attribute. The submitted field is identified by that name, and the control's current value is…"
            },
            {
              "id": "node-38072",
              "label": "Key Detail",
              "icon": "💡",
              "badge": "Standard",
              "summary": "An id identifies a control in the document; a name identifies its submitted field. They often match, but they serve different purposes."
            }
          ]
        }
      ]
    }
